def prime_length(string):
    """Return True if the length of the input string is a prime number, else False."""
    n = len(string)
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    i = 3
    while i * i <= n:
        if n % i == 0:
            return False
        i += 2
    return True


# Example usage / simple tests
if __name__ == "__main__":
    print(prime_length('Hello'))       # True (length 5)
    print(prime_length('abcdcba'))     # True (length 7)
    print(prime_length('kittens'))     # True (length 7)
    print(prime_length('orange'))      # False (length 6)
