def count_up_to(n):
    """Return a list of all prime numbers less than n."""

    def is_prime(num):
        if num < 2:
            return False
        if num == 2:
            return True
        if num % 2 == 0:
            return False
        limit = int(num ** 0.5) + 1
        for divisor in range(3, limit, 2):
            if num % divisor == 0:
                return False
        return True

    primes = []
    # Check every integer from 2 up to (but not including) n
    for candidate in range(2, n):
        if is_prime(candidate):
            primes.append(candidate)
    return primes


# Optional: quick tests when the module is run directly
if __name__ == "__main__":
    print(count_up_to(5))    # [2, 3]
    print(count_up_to(11))   # [2, 3, 5, 7]
    print(count_up_to(0))    # []
    print(count_up_to(20))   # [2, 3, 5, 7, 11, 13, 17, 19]
    print(count_up_to(1))    # []
    print(count_up_to(18))   # [2, 3, 5, 7, 11, 13, 17]
