import math

def closest_integer(value):
    """
    Return the integer closest to the number represented by value (string).
    If equidistant, round away from zero.

    Parameters:
    - value: string representing a number (int or float)

    Returns:
        int: the closest integer to the given number. For ties, choose the integer
               farther from zero (i.e., round away from zero).
    """
    num = float(value)          # convert the input string to a floating‑point number
    lower = math.floor(num)     # greatest integer ≤ num
    upper = math.ceil(num)      # smallest integer ≥ num

    diff_lower = abs(num - lower)
    diff_upper = abs(num - upper)

    if diff_lower < diff_upper:
        return int(lower)
    elif diff_upper < diff_lower:
        return int(upper)
    else:  # exactly halfway between two integers
        if num > 0:
            return int(upper)   # round up (away from zero for positive numbers)
        else:
            return int(lower)   # round down (more negative, away from zero)

# Simple test cases
if __name__ == "__main__":
    print(closest_integer("10"))      # 10
    print(closest_integer("15.3"))   # 15
    print(closest_integer("-14.5"))  # -15
