def compare_one(a, b):
    """
    Return the larger of a and b based on their numeric value.

    Parameters:
    - a: int, float, or str representing a real number (e.g., "2,3" uses comma as decimal separator)
    - b: same type

    Returns:
        The argument (a or b) whose numeric value is greater,
        preserving its original type. If the numeric values are equal,
        return None.
    """
    def to_number(val):
        if isinstance(val, str):
            # Replace comma with dot for decimal separator
            s = val.replace(',', '.')
            try:
                return float(s)
            except ValueError:
                raise ValueError(f"Cannot convert string '{val}' to a number")
        else:
            # For int or float, just convert to float for comparison
            return float(val)

    num_a = to_number(a)
    num_b = to_number(b)

    if num_a > num_b:
        return a
    elif num_b > num_a:
        return b
    else:
        return None
