def solve(s):
    """Return a new string where each alphabetic character has its case swapped.

    If the input string contains no letters at all, return the reversed string.
    """
    # Check if there is any letter in s
    if not any(ch.isalpha() for ch in s):
        return s[::-1]

    result = []
    for ch in s:
        if ch.isalpha():
            result.append(ch.swapcase())
        else:
            result.append(ch)
    return ''.join(result)


